      { w: "tropical", def: "describing hot, wet regions near the middle of the earth", sent: "We needed light clothes and bug spray for the ___ heat, where it stayed sticky even at night.", mis: ["tropikal", "tropicle", "tropicall"] },
      { w: "dissolve", def: "to disappear by mixing fully into a liquid", sent: "She stirred the powder slowly, watching it ___ until the water looked clear again.", mis: ["disolve", "dissolv", "disolveve"] }
